    h, w = len(grid), len(grid[0])

    # Find the repeated horizontal palette strip: the same ordered sequence of
    # nonzero colors appears in multiple adjacent rows.
    strip = None
    for r in range(h - 1):
        vals = tuple(v for v in grid[r] if v)
        if len(vals) < 2:
            continue
        if tuple(v for v in grid[r + 1] if v) == vals:
            end = r + 1
            while end + 1 < h and tuple(v for v in grid[end + 1] if v) == vals:
                end += 1
            strip = (r, end, list(vals))
            break
    if strip is None:
        raise ValueError('repeated palette strip not found')
    strip_top, strip_bottom, palette = strip

    # The color-1 object is the reference silhouette. Ignore the strip while
    # locating it, and use 8-way connectivity because the motifs touch at corners.
    remaining = {
        (r, c) for r in range(h) if not strip_top <= r <= strip_bottom
        for c in range(w) if grid[r][c] == 1
    }
    components = []
    while remaining:
        seed = remaining.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for nr in range(r - 1, r + 2):
                for nc in range(c - 1, c + 2):
                    if (nr, nc) in remaining:
                        remaining.remove((nr, nc))
                        comp.add((nr, nc))
                        stack.append((nr, nc))
        components.append(comp)
    glyph = min(components, key=lambda comp: min(r for r, c in comp))
    minr = min(r for r, c in glyph)
    maxr = max(r for r, c in glyph)
    minc = min(c for r, c in glyph)
    shape = {(r - minr, c - minc) for r, c in glyph}
    gh = maxr - minr + 1

    # Keep the reference color-1 motif in its corresponding palette slot and
    # replicate its silhouette once for each palette color.
    first = minr - palette.index(1) * gh
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        top = first + i * gh
        for dr, dc in shape:
            rr, cc = top + dr, minc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
